/**
 * User-facing copy for every error code the UI can receive.
 *
 * Single source of truth: components never invent their own wording, and a Thai
 * locale can be added later by swapping this map. Backend codes come from
 * docs/API-CONTRACT.md §8; `BFF_*` / `UPSTREAM_*` codes are generated by the BFF.
 */

export const ERROR_MESSAGES: Record<string, string> = {
  // --- generic ---
  BAD_REQUEST: 'The request could not be processed. Check the values and try again.',
  VALIDATION_ERROR: 'Some values are not valid. Check the highlighted fields.',
  INVALID_ID: 'That identifier is not valid.',
  INVALID_PARAMETER: 'One of the filter values is not valid.',
  NOT_FOUND: 'Not found. It may have been removed, or you may not have access to it.',
  INTERNAL_ERROR: 'The server could not complete the request. Try again in a moment.',
  UPSTREAM_ERROR: 'The server could not complete the request. Try again in a moment.',

  // --- auth ---
  INVALID_CREDENTIALS: 'Incorrect username or password.',
  TOO_MANY_ATTEMPTS: 'Too many sign-in attempts. Wait a few minutes and try again.',
  UNAUTHORIZED: 'Your session is no longer valid. Please sign in again.',
  WEAK_PASSWORD: 'That password does not meet the minimum requirements.',
  PASSWORD_REUSED: 'The new password must be different from the current one.',
  FORBIDDEN: 'You do not have permission to perform this action.',
  SELF_APPROVAL_FORBIDDEN: 'You cannot review or issue a request you created yourself.',

  // --- products / stock ---
  DUPLICATE_SKU: 'A product with this SKU already exists.',
  PRODUCT_INACTIVE: 'This product is inactive, so stock cannot be received or requested.',
  INSUFFICIENT_STOCK: 'There is not enough stock to fulfil every item.',
  INVALID_STATE: 'This request is no longer in a state that allows that action.',
  STOCK_OVERFLOW: 'The resulting stock would exceed the maximum supported quantity.',
  DUPLICATE_ITEM: 'The same product appears more than once in the request.',
  DUPLICATE_REQUEST_NUMBER: 'A request with this number already exists. Try again.',
  INVALID_IDEMPOTENCY_KEY: 'The idempotency key is not valid. Retry the action.',

  // --- BFF-generated ---
  BFF_NO_SESSION: 'You are not signed in.',
  BFF_SESSION_EXPIRED: 'Your session expired. Please sign in again.',
  BFF_CSRF_FAILED: 'The request was blocked for security reasons. Reload the page and try again.',
  BFF_BAD_REQUEST: 'The request could not be read.',
  BFF_PAYLOAD_TOO_LARGE: 'The request is too large.',
  BFF_RATE_LIMITED: 'Too many attempts. Wait a moment and try again.',
  BFF_ROUTE_NOT_ALLOWED: 'That operation is not available.',
  UPSTREAM_UNAVAILABLE: 'The API is not reachable right now. Check that the backend is running.',
  UPSTREAM_TIMEOUT: 'The API took too long to respond. Try again.',
};

/** Returns copy for a code, falling back to the supplied message or a generic line. */
export function messageForCode(code: string, fallback?: string): string {
  const known = ERROR_MESSAGES[code];
  if (known) {
    return known;
  }
  if (fallback && fallback.trim().length > 0) {
    return fallback;
  }
  return 'Something went wrong. Try again.';
}
